(() => {
  'use strict';
  const app = document.querySelector('#app');
  const params = new URLSearchParams(location.search);
  const stored = key => {try{return localStorage.getItem(key)}catch{return null}};
  const persist = (key,value) => {try{localStorage.setItem(key,value)}catch{}};
  const themes = ['cobalt','acid','iris'];
  let theme = params.get('design') || stored('gaac-design-v2') || 'iris';
  if(!themes.includes(theme)) theme='iris';
  const typefaces=['unbounded','michroma','syncopate'];
  let typeface=params.get('type')||stored('gaac-typeface')||'michroma';
  if(!typefaces.includes(typeface))typeface='michroma';
  const cnFonts=['chill','system'];
  let cnFont=params.get('cn')||stored('gaac-cn-font')||'chill';
  if(!cnFonts.includes(cnFont))cnFont='chill';
  let lang = params.get('lang') || stored('gaac-language') || 'en';
  if(!['en','zh'].includes(lang))lang='en';
  let disposeArt, renderVersion=0;
  const t=(en,zh)=>lang==='zh'?zh:en;
  const arrow='<span class="arrow" aria-hidden="true">↗</span>';
  const right='<span class="arrow" aria-hidden="true">→</span>';
  const href=(path,design=theme)=>{const u=new URL(path,location.origin);u.searchParams.set('design',design);u.searchParams.set('lang',lang);u.searchParams.set('type',typeface);u.searchParams.set('cn',cnFont);return u.pathname+u.search+u.hash;};
  const link=(path,label,cls='text-link',design=theme)=>`<a class="${cls}" href="${href(path,design)}">${label}${arrow}</a>`;
  const eyebrow=(label,dot=false)=>`<div class="eyebrow">${dot?'<span class="dot"></span>':''}${label}</div>`;
  const sectionLabel=(n,label)=>`<div class="section-label mono"><span>${n}</span><span>${label}</span></div>`;
  const notice=text=>`<div class="notice">${text}</div>`;
  const rows=items=>items.map((r,i)=>`<div class="info-row"><span class="micro">${String(i+1).padStart(2,'0')}</span><h3>${r[0]}</h3><p>${r[1]}</p></div>`).join('');
  const table=(headers,body)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const faq=items=>items.map(r=>`<details class="faq"><summary>${r[0]}</summary><p>${r[1]}</p></details>`).join('');
  const article=(id,title,content)=>`<section class="article-section" id="${id}"><h2>${title}</h2>${content}</section>`;
  const sidebar=items=>`<aside class="sub-sidebar"><div class="micro">${t('On this page','本页内容')}</div>${items.map(r=>`<a href="#${r[0]}">${r[1]}</a>`).join('')}</aside>`;
  const pageHero=(label,title,desc,cta='')=>`<div class="wrap"><section class="page-hero"><div>${eyebrow(label,true)}<h1>${title}</h1></div><div><p>${desc}</p>${cta}</div></section></div>`;
  const subLayout=(items,content)=>`<div class="wrap sub-layout">${sidebar(items)}<div>${content}</div></div>`;
  const oaicMark=()=>theme==='acid'?'/assets/oaic-logo-dark.png':'/assets/oaic-logo-light.png';
  function header(page){return `<div class="wrap"><header class="site-header"><div class="brand"><a class="gaac-home" href="${href('/')}" aria-label="GAAC — Home"><img src="/assets/gaac-logo.png" alt="GAAC — Grand Agentic AI Challenge" width="156" height="52"></a><a class="brand-by" href="https://www.oaic.ai/" target="_blank" rel="noopener" aria-label="OAIC — 官网"><span class="by-label">AN INITIATIVE BY</span><img class="oaic-mark" src="${oaicMark()}" alt="OAIC — 开放智能体产业联盟" width="92" height="42"></a></div><nav class="main-nav" id="main-nav" aria-label="${t('Main navigation','主导航')}"><a class="nav-link ${page==='challenge'?'active':''}" href="${href('/challenge/')}">${t('The challenge','挑战赛')}</a><a class="nav-link ${page==='ecosystem'?'active':''}" href="${href('/ecosystem/')}">${t('The ecosystem','开放生态')}</a><details class="nav-dropdown"><summary class="nav-link">${t('Participate','参与共建')} <span>⌄</span></summary><div class="dropdown-panel">${[['partners',t('Sponsors & partners','赞助与资源伙伴')],['teams',t('Teams & developers','参赛与开源团队')],['enterprise',t('Enterprises','企业与行业用户')],['research',t('Research & education','高校与研究机构')]].map(r=>`<a href="${href('/'+r[0]+'/')}">${r[1]}${arrow}</a>`).join('')}</div></details><a class="nav-link ${page==='resources'?'active':''}" href="${href('/resources/')}">${t('Resources','资料中心')}</a></nav><div class="header-actions"><button class="language" data-action="language" aria-label="${t('Switch to Chinese','切换为英文')}">${t('中文','EN')}</button>${link('/involve/',t('Let’s build','一起共建'),'button small dark')}<button class="mobile-toggle" data-action="menu" aria-expanded="false" aria-controls="main-nav" aria-label="${t('Open navigation','打开导航')}">☰</button></div></header></div>`;}
  function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-top"><a class="footer-brand" href="https://www.oaic.ai/" target="_blank" rel="noopener" aria-label="OAIC — 开放智能体产业联盟"><img class="oaic-mark" src="${oaicMark()}" alt="OAIC — Open Agentic Industry Consortium" width="190"></a><div class="footer-nav"><a href="${href('/challenge/')}">${t('The challenge','挑战赛')}</a><a href="${href('/partners/')}">${t('Partnerships','伙伴合作')}</a><a href="${href('/research/')}">${t('Research','高校研究')}</a><a href="${href('/resources/')}">${t('Resources','资料中心')}</a><a href="https://www.oaic.ai/" target="_blank" rel="noopener">oaic.ai ↗</a></div></div><div class="footer-bottom"><p>${t('A collaboration proposal in development. Team counts, scoring details, dates, and post-event outputs are planning targets, subject to validation and final rules.','本项目处于共创筹备阶段。团队数量、评分细则、赛程及赛后成果均为规划目标，须经验证并以最终规则为准。')}</p><span>© ${new Date().getFullYear()} OAIC · ${t('Open. Practical. Collaborative.','开放 · 实战 · 协作')}<br>${t('Based on proposal V1.3 · 27 October 2026','依据提案 V1.3 · 2026 年 10 月 27 日')}</span></div></div></footer>`;}
  function dock(){return `<aside class="design-dock" aria-label="${t('Compare website design directions','对比网站设计方向')}"><span class="dock-label">${t('Design','设计')} 0${themes.indexOf(theme)+1}</span>${themes.map((v,i)=>`<button class="theme-choice" data-theme="${v}" data-action="theme" aria-label="${['Electric Cobalt','Acid Signal','Sky Editorial'][i]}" aria-pressed="${v===theme}" title="${['Electric Cobalt','Acid Signal','Sky Editorial'][i]}">${v}</button>`).join('')}<span class="dock-divider"></span><a class="dock-compare" href="${href('/directions/')}">${t('Compare & film ideas','对比设计与视频灵感')} ↗</a></aside>`;}
  function cta(){return `<div class="wrap"><section class="cta-section"><div><h2>${t('The next chapter<br>is a collective effort.','下一步，<br>一起把它做出来。')}</h2><p>${t('Bring your expertise, a real-world problem, or the resources to make open intelligence work.','带来你的专业能力、一个真实问题，或推动开源智能体落地的资源。')}</p></div>${link('/involve/',t('Find your way in','找到你的参与方式'),'button')}</section></div>`;}
  function taskArt(type){
    const start=`<svg viewBox="0 0 360 200" aria-hidden="true"><defs><filter id="sh-${type}" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="8" stdDeviation="8" flood-opacity=".08"/></filter></defs>`;
    if(type===0)return start+`<g transform="translate(84 35) rotate(-8 95 65)" filter="url(#sh-0)"><rect width="190" height="125" fill="var(--soft)" stroke="currentColor" stroke-opacity=".25"/><rect x="16" y="18" width="70" height="5" fill="currentColor"/><rect x="16" y="31" width="43" height="3" fill="currentColor" opacity=".35"/><path d="M25 98 57 60 87 98M113 98V65H130V98M140 98V49H157V98" fill="none" stroke="currentColor" stroke-width="6"/><path d="M176 12h7v7M7 106v7h7" fill="none" stroke="currentColor"/></g><g transform="translate(115 65) rotate(5 95 65)" filter="url(#sh-0)"><rect width="175" height="105" fill="var(--paper)" stroke="currentColor" stroke-opacity=".4"/><text x="14" y="20" fill="currentColor" font-family="Arial" font-size="8" letter-spacing="1">OPEN INTELLIGENCE</text><path d="M14 38h73M14 45h51" stroke="currentColor" stroke-width="3" opacity=".3"/><path d="M113 80 136 42 159 80M130 74h13" fill="none" stroke="currentColor" stroke-width="6"/><rect x="14" y="68" width="66" height="20" fill="var(--soft)"/></g></svg>`;
    if(type===1)return start+`<g transform="translate(70 25)" filter="url(#sh-1)"><rect width="220" height="150" fill="var(--paper)" stroke="currentColor" stroke-opacity=".3"/><path d="M0 25h220M34 0v150" stroke="currentColor" stroke-opacity=".2"/><text x="11" y="17" fill="currentColor" font-family="monospace" font-size="8">ƒx</text><g stroke="currentColor" stroke-opacity=".1"><path d="M34 50h186M34 75h186M34 100h186M34 125h186M80 25v125M126 25v125M172 25v125"/></g><path d="M55 111 87 91 120 99 151 67 191 48" stroke="currentColor" stroke-width="3" fill="none"/><path d="M55 111 87 91 120 99 151 67 191 48V133H55Z" fill="currentColor" opacity=".08"/><g fill="currentColor"><circle cx="55" cy="111" r="4"/><circle cx="87" cy="91" r="4"/><circle cx="120" cy="99" r="4"/><circle cx="151" cy="67" r="4"/><circle cx="191" cy="48" r="4"/></g><rect x="150" y="18" width="57" height="20" fill="var(--soft)"/><text x="158" y="31" fill="currentColor" font-family="monospace" font-size="8">TRACEABLE</text></g></svg>`;
    return start+`<g stroke="currentColor" fill="none" stroke-opacity=".45"><path d="M91 58 175 105 269 50M175 105 268 143M175 105 102 154"/><circle cx="175" cy="105" r="31" stroke-opacity=".16"/><circle cx="175" cy="105" r="46" stroke-opacity=".1"/></g><g fill="var(--paper)" stroke="currentColor" stroke-opacity=".4"><rect x="60" y="25" width="64" height="76" transform="rotate(-10 92 63)"/><rect x="241" y="20" width="53" height="65" transform="rotate(9 267 52)"/><rect x="245" y="117" width="53" height="56" transform="rotate(-5 270 145)"/><rect x="78" y="135" width="50" height="40" transform="rotate(5 103 155)"/></g><g stroke="currentColor" stroke-width="2" opacity=".35"><path d="M76 45h30M75 52h28M74 60h23M252 39h26M253 46h22M256 135h28M256 142h22M88 148h27M89 155h21"/></g><circle cx="175" cy="105" r="17" fill="currentColor"/><path d="m168 105 5 5 9-10" fill="none" stroke="var(--paper)" stroke-width="2"/></svg>`;
  }
  const tasks=()=>[
    [t('Editable presentations','可编辑演示文稿'),t('From a fact pack to a native, editable deck. Every number accurate. Every essential element yours to change.','从事实资料到原生可编辑的 PPT。数字准确，关键元素可以修改，保存重开依然可靠。'),'PPTX',t('Content → composition → verification','内容 → 排版 → 编辑验证')],
    [t('Financial analysis','财报分析与可视化'),t('Turn financial reports into traceable workbooks, editable charts, and conclusions that the data actually supports.','把财报转为可追溯工作簿、可编辑图表，以及有数据支持的分析结论。'),'XLSX',t('Data → analysis → evidence','数据 → 分析 → 溯源核验')],
    ['Deep Research',t('Find, compare, and connect evidence in a frozen local library. Clear sources. Honest limits. Useful answers.','在冻结的本地资料库中检索、比较与综合证据。来源明确，局限透明，结论可核验。'),'REPORT',t('Sources → synthesis → insight','来源 → 综合 → 证据核验')]
  ];
  function taskCards(){return `<div class="task-grid">${tasks().map((v,i)=>`<a class="task-card" href="${href('/challenge/')}#applications"><div class="task-art">${taskArt(i)}</div><span class="micro">0${i+1} / ${v[2]}</span><h3>${v[0]}</h3><p>${v[1]}</p><div class="task-bottom"><span>${v[3]}</span>${arrow}</div></a>`).join('')}</div>`;}
  function home(){
    const titles={cobalt:t('Built open.<br>Proven <em>real.</em>','开放共建。<br>实战<em>验证。</em>'),acid:t('Open minds.<br><em>Real impact.</em>','开放智慧。<br><em>真实成果。</em>'),iris:t('OPEN BY NATURE.<br><em>BUILT TOGETHER.</em>','因开放而生。<br>因<em>协作而不同。</em>')};
    const audience=[['partners',t('Sponsors & resource partners','赞助与资源伙伴'),t('Turn infrastructure and expertise into shared, verifiable assets.','让算力、基础设施与工程支持，沉淀为可复用的共同资产。')],['teams',t('Teams & open-source builders','参赛与开源团队'),t('Prove your full-stack craft. Build a body of work others can trust.','用可重建、可验收的交付，证明全栈工程能力。')],['enterprise',t('Enterprises & industry','企业与行业用户'),t('Start with one real task. Discover what your team can put to work.','从一个真实任务开始，验证方案，也建设自己的采用能力。')],['research',t('Universities & researchers','高校与研究机构'),t('Connect real engineering problems with reproducible research.','让真实工程问题连接可复现研究、课程与学生实践。')]];
    return `<div class="wrap"><section class="hero"><div class="hero-copy">${eyebrow('GRAND AGENTIC AI CHALLENGE',true)}<h1>${titles[theme]}</h1><p class="hero-description">${t('A full-stack challenge for open-source agents.<br>Real tasks. Independent validation.<br>A foundation for what comes next.','一场面向开源智能体的全栈挑战。<br>以真实任务检验能力，以独立验证连接产业。<br>让一次实战，成为持续创新的起点。')}</p><div class="hero-actions">${link('/challenge/',t('Explore the challenge','了解挑战赛'),'button')}${link('/ecosystem/',t('Beyond the competition','不止于一场比赛'))}</div><p class="hero-footnote"><span class="dot"></span>${t('In development · Built for lasting collaboration','筹备共创中 · 为持续合作而构建')}</p></div><div class="hero-art" role="group" aria-label="${t('Two interlocking open triangular forms, inspired by the GAAC logo','受 GAAC 标志启发的两组开放三角形雕塑')}"><canvas id="sculpture" aria-hidden="true"></canvas><div class="art-top"><span class="micro">${theme==='acid'?'SYS. 001 / OPEN NETWORK':theme==='iris'?'A STUDY IN COLLECTIVE FORM':'FORM 001 / OPEN ASSEMBLY'}</span><span class="art-circle">↗</span></div><button class="motion-toggle" aria-label="Pause sculpture motion" aria-pressed="true">Ⅱ</button><div class="art-caption"><span>INFERENCE × KV CACHE × AGENT<br>${t('A shared foundation. Infinite possibilities.','共同底座，开放可能。')}</span><span class="plus">+</span></div></div></section><section class="stats" aria-label="${t('Challenge at a glance — planning targets','挑战赛概览——规划目标')}"><p class="stats-label">${t('One shared platform.<br>A higher standard of proof.','同一套平台，<br>经得起验证的交付。')}</p>${[[168,t('hours per team','小时 / 每队')],[5,t('invited teams · target','目标定邀团队')],[3,t('real-world applications','类真实应用')],[90,t('days beyond the challenge','天赛后持续共建')]].map((v,i)=>`<div class="stat"><div class="stat-value">${v[0]}${i===0?'<span>h</span>':i===3?'<span>d</span>':''}</div><p class="stat-label">${v[1]}</p></div>`).join('')}</section><section class="section">${sectionLabel('01',t('THE WORK, NOT THE HYPE','以交付，见实力'))}<div class="section-header"><h2>${t('Intelligence that<br>has something to show.','智能，不止回答。<br>更要交付。')}</h2><p class="section-intro">${t('Three essential applications. One integrated system. Every team is challenged to deliver work that can be opened, edited, traced, and independently verified.','三类真实应用，检验同一套全栈系统。每一支团队都要交付可以打开、修改、追溯，并由他人独立验收的成果。')}</p></div>${taskCards()}</section><section class="section pathways">${sectionLabel('02',t('FIND YOUR PLACE','找到你的共建位置'))}<div class="section-header"><h2>${t('Different expertise.<br>One open ambition.','不同专业，<br>同一个开放愿景。')}</h2>${link('/involve/',t('Ways to get involved','探索参与方式'))}</div><div class="path-list">${audience.map((v,i)=>`<a class="path-item" href="${href('/'+v[0]+'/')}"><span class="micro">0${i+1}</span><div><h3>${v[1]}</h3><p>${v[2]}</p></div>${arrow}</a>`).join('')}</div></section></div><section class="manifesto"><div class="wrap"><div>${eyebrow(t('03 / BEYOND 168 HOURS','03 / 168 小时之外'))}<h2>${t('A challenge ends.<br>An ecosystem<br>keeps building.','比赛有终点。<br>共建，无止境。')}</h2><p>${t('The competition is the starting point. OAIC connects the results to a living Testbed, joint research, reusable templates, education, and enterprise practice.','挑战赛只是起点。OAIC 用持续 Testbed，把成果连接到联合研究、规范模板、课程与企业实践，让经验回到下一轮创新。')}</p></div><div class="loop-list">${[t('Real-world needs','真实需求与研究议题'),t('Open-source delivery','全栈实战与开源交付'),t('Independent validation','Testbed 持续验证'),t('Research, templates & education','研究、规范、模板与课程'),t('Enterprise adoption & feedback','企业实践与问题回流')].map((v,i)=>`<a href="${href('/ecosystem/')}" class="loop-item"><span class="micro">0${i+1}</span>${v}${right}</a>`).join('')}</div></div></section>${cta()}`;
  }
  function challenge(){return pageHero(t('THE CHALLENGE / OVERVIEW','挑战赛 / 概览'),t('168 hours.<br><em>Proof at every layer.</em>','168 小时。<br><em><span class="keep-word">全栈实力，</span><span class="keep-word">逐层验证。</span></em>'),t('Inference. KV Cache. Agents. Bring them together to deliver three real applications on one shared platform.','推理、KV Cache、Agent 协同，在统一平台上完成三类真实应用，以独立验收检验端到端能力。'),link('/teams/',t('For teams & developers','参赛团队指南'),'button'))+subLayout([['format',t('The format','两阶段赛制')],['applications',t('Three applications','三类应用')],['platform',t('Shared platform','共同平台')],['assessment',t('Assessment','评测与评分')],['faq',t('Questions','常见问题')]],
    article('format',t('Build first. Then prove it.','先搭建，再验证。'),`<p>${t('The proposed first edition is invitation-only: approximately eight candidate teams approached, with five selected. Each team has up to three people and a designated captain. Teams use the same EdgePod sequentially, with a full reset between windows.','首届计划采用精英定邀：拟触达约 8 支候选团队，筛选 5 队。每队最多 3 人并指定队长，按抽签顺序使用同一套 EdgePod，队间重装干净环境。')}</p><div class="phase-grid"><div class="phase"><span class="micro">${t('PHASE 01 / HOURS 0–30','阶段 01 / 0—30 小时')}</span><h3>${t('Open-book engineering','开卷搭建与优化')}</h3><p>${t('Build and optimize the local full-stack system. The six original infrastructure tasks are retained. Any tools may be used, including Codex and Claude Code.','构建并优化本地全栈系统，保留原六项基础考题。允许使用任何工具，包括 Codex 和 Claude Code。')}</p><div class="phase-score">25 <span>${t('points','分')}</span></div></div><div class="phase accent"><span class="micro">${t('PHASE 02 / HOURS 30–168','阶段 02 / 30—168 小时')}</span><h3>${t('Offline application delivery','断网闭卷应用交付')}</h3><p>${t('Complete all three application categories using local DeepSeek, an open-source Harness, and frozen tools. No online agents or external model APIs.','使用本地 DeepSeek、开源 Harness 与冻结工具，完成全部三类应用。禁止在线 Agent 与外部模型 API。')}</p><div class="phase-score">75 <span>${t('points','分')}</span></div></div></div>${notice(t('The 25/75 stage split is retained. Detailed phase-two scoring, task counts, budgets, and thresholds are proposals to be calibrated and frozen before the first team starts.','保留 25 / 75 分两阶段结构。第二阶段细分评分、题量、预算与门槛均为建议，须在首队开赛前校准冻结。'))}`)+
    article('applications',t('Three applications. All required.','三类应用，全部必做。'),rows(tasks().map(v=>[v[0],v[1]]))+`<p>${t('Images are supplied uniformly. Research uses a frozen local library, with version and cutoff dates recorded. Editable elements must remain editable; research claims must map to evidence.','图片素材统一提供。研究采用冻结的本地资料库，明确版本及截止时间。可编辑内容必须保持可编辑，关键研究主张必须映射到证据。')}</p>`)+
    article('platform',t('Same hardware. Equal windows.','同一硬件，相同窗口。'),table([t('Shared EdgePod','共用 EdgePod'),t('Configuration','配置')],[['GPU','16 × RTX PRO 6000 Max-Q'],['NVMe','4 × 64 TB'],['Network','400 GbE'],[t('Team window','每队正式窗口'),'168 '+t('hours','小时')],[t('Scheduling','上机方式'),t('Sequential, by draw; maintenance outside team windows','抽签后顺序上机，队间维护单独排期')]])+`<p>${t('One platform is shared across the event. The theoretical ceiling is 2,688 GPU-hours per team window; actual availability is lower after installation, maintenance, resets, and evaluation overhead.','所有团队共用一套平台。单窗口理论上限为 2,688 GPU 卡时，实际可用量须扣除安装、维护、重置与公共评测开销。')}</p>`)+
    article('assessment',t('Quality comes first.','先看质量，再谈效率。'),`<p>${t('Independent acceptance checks the result, editability, evidence, and reproducibility. Time, complete cost, and logical tokens are compared only after quality and correctness gates are met.','独立验收检查结果、可编辑性、证据与可复现性。先通过质量与正确性门禁，再比较时间、完整成本和逻辑 token。')}</p>`+table([t('Proposed phase-two score','第二阶段建议评分'),t('Per category','每类分值')],[[t('Result quality','结果质量'),'15'],[t('Efficiency under quality constraints','质量约束下的效率'),'6'],[t('Reproducibility & evidence','复现与证据'),'4'],[t('Three categories total','三类合计'),'75']])+link('/resources/',t('Read the detailed planning handbook','查看详细规则与筹备手册')))+
    article('faq',t('A few things to know.','你可能想了解。'),faq([[t('Can teams use online coding agents?','能否使用在线编程 Agent？'),t('Yes during hours 0–30. During phase two, the network is disconnected and online agents, external model APIs, remote solving, and cross-team answer sharing are prohibited.','0—30 小时开卷阶段可以。第二阶段断网，禁止在线 Agent、外部模型 API、远程解题与跨队交换答案。')],[t('Is Deep Research possible without the internet?','断网如何做 Deep Research？'),t('The task is to retrieve, read, compare, and synthesize a frozen local library. It tests evidence synthesis rather than real-time web search. Missing information must be disclosed.','在冻结本地资料库中检索、阅读、比较与综合，检验证据综合能力，不考实时上网搜索。资料缺失时必须说明局限。')],[t('When will the challenge run?','赛事何时举办？'),t('The planning target is an early-December start and completion by late January or before Spring Festival. Exact dates depend on platform readiness and final rules; there are no confirmed opening dates yet.','筹备目标为 12 月初启动，次年 1 月底或春节前完成。具体日期取决于平台就绪与规则冻结，目前尚未正式确认。')],[t('Will this be a large conference or bootcamp?','是否举办大型大会或训练营？'),t('The first edition focuses on invited engineering teams and shared-platform validation. No beginner bootcamp or large conference is planned.','首届聚焦精英定邀与共享平台实战验证，不安排初学者训练营或大型大会。')]])))+cta();}
  function ecosystem(){return pageHero(t('THE ECOSYSTEM / OPEN BY DESIGN','开放生态 / 共建机制'),t('A competition.<br><em>A continuing contribution.</em>','一场赛事。<br><em>持续形成共同成果。</em>'),t('OAIC connects engineering, research, standards, education, and adoption through a shared cycle of delivery and validation.','OAIC 以交付与验证为共同语言，连接工程、研究、规范、教育与企业采用。'))+subLayout([['loop',t('Collaboration loop','协作闭环')],['testbed','Testbed'],['assets',t('Shared assets','共同资产')],['foundation',t('Five capabilities','五类能力')],['roadmap',t('90-day roadmap','90 天路线图')]],
    article('loop',t('From real needs. Back to real needs.','从真实需求出发，回到真实实践。'),rows([[t('Define & select','需求与立项'),t('Collect business and research questions. Review value, feasibility, priorities, owners, and resources.','企业与研究伙伴提出需求；业务与技术并行初筛，确认优先级、负责人和资源。')],[t('Deliver & verify','交付与验证'),t('Use the challenge and open engineering to produce working systems, then independently test them in the Testbed.','通过赛事与开放工程形成系统，再以 Testbed 和独立验收检验。')],[t('Publish & reuse','发布与复用'),t('Resolve issues, review licenses and evidence, version accepted outputs, and feed them into templates, courses, and enterprise practice.','问题回流，完成许可与证据检查；按版本接受发布，进入模板、课程与企业实践。')]])+faq([[t('Explore the full nine-step OAIC collaboration loop','展开 OAIC 九步产业协作闭环'),t('1. Needs and topics → 2. Parallel business and technical screening → 3. Portfolio priorities → 4. Planning and ownership → 5. Collaborative delivery → 6. Public validation → 7. Issue feedback → 8. Acceptance and publication → 9. Reuse and iteration. Business feedback returns to scenarios and ROI methods; technical feedback returns to research, architecture, open source, and specifications.','1. 需求与议题输入 → 2. 业务与技术并行初筛 → 3. 组合优先级确认 → 4. 计划与立项 → 5. 协同交付 → 6. 公开验证 → 7. 问题回流 → 8. 接受与发布 → 9. 复用与迭代。业务问题回到场景与 ROI 方法，技术问题回到研究、架构、开源与规范。')]]))+
    article('testbed',t('A living environment for proof.','让验证持续发生。'),`<p>${t('The planned Testbed preserves configurations, scenario versions, acceptance results, costs, and failures. It gives future versions and research ideas a repeatable place to be tested.','计划中的 Testbed 保留配置、场景版本、验收结果、成本与失败记录，为版本迭代与研究方案提供可重复的检验环境。')}</p>`+rows([[t('Public reproduction','公开复现区'),t('Open or synthetic scenarios, traceable versions, reference configurations, and teaching experiments.','公开或合成场景、版本可追溯的参考配置与课程实验。')],[t('Controlled collaboration','受控共创区'),t('Project-specific authorization for joint research, configuration comparisons, and interoperability tests.','按项目授权开展联合研究、跨配置对照与互操作测试。')],[t('Enterprise validation','企业私有区'),t('The enterprise retains control of its data, systems, permissions, and production actions.','企业保留数据、系统、权限与生产动作的控制权。')]])+notice(t('A sustained Testbed needs capacity, maintainers, an operating budget, and response ownership. Passing a Testbed experiment is not production certification.','持续运行需要容量、维护者、预算与响应责任。通过 Testbed 实验不等于获得生产认证。')))+
    article('assets',t('What the work can leave behind.','让成果留下来。'),`<div class="research-grid">${[[t('Open-source reference packages','开源全栈参考包'),t('Source, deployment scripts, locked versions, licenses, and recovery instructions.','源码、部署脚本、锁定版本、许可证与恢复说明。')],[t('Usable application artifacts','可用应用成果'),t('Editable presentations, analysis workbooks, research reports, and their evidence.','可编辑演示稿、分析工作簿、研究报告及对应证据。')],[t('A continuous Testbed','持续 Testbed'),t('Frozen baselines, repeatable scenarios, regression and failure records.','冻结基线、可重复场景、回归与故障记录。')],[t('Evaluation specifications','评测与计量草案'),t('Task contracts, metrics, trace fields, and complete-cost methods.','任务契约、指标、trace 字段与完整成本方法。')],[t('Industry templates','行业与运营模板'),t('Business context, action contracts, acceptance conditions, and reuse limits.','业务上下文、动作契约、验收条件与复用边界。')],[t('Reproducible research','联合研究复现包'),t('Questions, controls, data permissions, methods, and limitations.','问题、对照、数据授权、方法与局限。')],[t('Courses & teaching materials','课程与实验教材'),t('Role-based labs, assessment anchors, and independent project work.','分角色实验、评价锚点与独立项目。')],[t('Contribution records','贡献与人才档案'),t('Consented records of real work, maintenance, and collaboration interests.','经授权的实际贡献、维护与协作意愿记录。')]].map((v,i)=>`<div class="research-card"><span class="micro">0${i+1} / ${t('PLANNED OUTPUT','计划成果')}</span><h3>${v[0]}</h3><p>${v[1]}</p></div>`).join('')}</div>`)+
    article('foundation',t('Five capabilities. One shared direction.','五类核心能力，协同演进。'),rows([['AOS',t('Agent orchestration, task lifecycle, controlled tools, isolation, and resource governance.','智能体编排、任务生命周期、受控工具、隔离与资源治理。')],['ASE',t('Engineering and quality across requirements, context, execution, artifacts, and independent tests.','贯穿需求、上下文、执行、工件与独立测试的工程质量。')],['ASG',t('Operational semantics connecting business objects, data, decisions, actions, and evidence.','连接业务对象、数据、决策、动作与证据的运营语义。')],['Open Token',t('Native resource usage, budgets, reservations, receipts, and transparent allocation.','原生资源用量、预算、预留、回执与透明分摊。')],['OAI Marketplace',t('Discover and reuse versioned outputs with licenses, validation status, and clear boundaries.','按版本、许可证、验证状态与适用边界发现和复用成果。')]]))+
    article('roadmap',t('After the final team, keep building.','最后一队结束，下一轮共建开始。'),rows([['01–30 '+t('days','天'),t('Open-source audit, independent reproduction, first Benchmark, and named maintainers. Target: collect five solution packages, with their reproduction status made clear.','开源审计、独立复现、Benchmark 首版与维护分工。目标汇集 5 套方案，并明确复现状态。')],['31–60 '+t('days','天'),t('Testbed regression, joint research, template review, enterprise trials, and course pilots.','推进 Testbed 回归、联合研究、规范模板评审、企业试用与课程试讲。')],['61–90 '+t('days','天'),t('Review enterprise pilots, research and teaching results; update the reference architecture and ongoing maintenance plan.','完成企业试点阶段验收、研究与课程复盘，更新参考架构与持续维护安排。')]])+notice(t('These are planned milestones after all team windows finish, not capabilities or partnerships already delivered.','以上为全部队伍结束后的计划里程碑，不代表能力与合作已经交付。'))))+cta();}
  function partners(){return pageHero(t('FOR SPONSORS & RESOURCE PARTNERS','面向赞助与资源伙伴'),t('Make your contribution<br><em>compound.</em>','让每一份投入，<br><em>形成长期价值。</em>'),t('Help build an open foundation that lasts beyond the event: reference systems, adaptation feedback, research, and a community of proven builders.','把资源转化为长期可复用的参考系统、适配反馈、研究与人才网络，让合作价值延续到赛事之外。'),link('/involve/?role=partner',t('Explore a partnership','探索合作方式'),'button'))+subLayout([['contribute',t('Ways to contribute','合作方式')],['value',t('What you can expect','合作价值')],['reporting',t('Reports & independence','报告与独立性')]],
    article('contribute',t('Resources become shared assets.','让资源成为共同资产。'),rows([[t('Compute & infrastructure','算力与基础设施'),t('Support GPU hosting, storage, networking, operations, or post-event Testbed capacity. Agree on scope, usage records, and maintenance ownership.','支持 GPU 托管、存储、网络、运维或赛后 Testbed 容量，明确范围、用量记录与维护责任。')],[t('Engineering & tools','工程与工具支持'),t('Contribute systems expertise, component integration, diagnostics, independent testing, or reproducibility support.','贡献系统能力、组件集成、诊断、独立测试或复现支持。')],[t('Program & maintenance support','公共项目与维护支持'),t('Help sustain coordination, public outputs, independent evaluation, and the maintainers who keep them useful.','支持项目协调、公共成果、独立评测与持续维护。')],[t('Scenarios & expertise','场景与专业经验'),t('Bring a bounded business problem, authorized sample tasks, and experts who can define acceptance.','提供有边界的业务问题、获授权的示例任务，以及能够定义验收的领域专家。')]]))+
    article('value',t('An outcome you can point to.','每一项价值，都有成果可核对。'),`<div class="big-statement">${t('Reference configurations.<br>Honest adaptation feedback.<br><em>People with a record of delivery.</em>','可复核的参考配置。<br>真实的适配反馈。<br><em>有交付记录的人才与团队。</em>')}</div><p>${t('Agree on resource-use reports, milestone deliverables, acknowledgement, technical exchanges, and authorized case studies. The deeper value is a clearer understanding of how infrastructure behaves under real workloads.','共同约定资源报告、里程碑交付、品牌鸣谢、技术交流与授权案例。更长期的价值，是看清基础设施在真实任务中的表现与工程边界。')}</p>`)+
    article('reporting',t('Credibility is part of the deliverable.','可信，是合作成果的一部分。'),rows([[t('Day 30 report','赛后 30 天报告'),t('Resource contribution and actual usage, public artifacts, passed and failed checks, reproduction status, and unresolved issues.','资源投入与实际使用、公开成果、通过与未通过的验收范围、复现状态及遗留问题。')],[t('Day 90 review','赛后 90 天复盘'),t('Ongoing contributors, research and course progress, authorized enterprise exchanges, pilot status, and a plan for continued work.','持续贡献者、研究课程进展、授权企业交流、试点状态与后续计划。')]])+notice(t('Resource support does not influence technical results. Reviewers disclose conflicts; contact sharing and case publication require consent. Partnership terms and deliverables are defined together.','资源支持不影响技术结论。评审须披露利益冲突，联系人共享与案例发布须经同意。具体合作范围与交付由双方共创确认。'))))+cta();}
  function teams(){return pageHero(t('FOR TEAMS & OPEN-SOURCE BUILDERS','面向参赛与开源团队'),t('Build something<br><em>others can build on.</em>','用你的实力，<br><em>构建他人的起点。</em>'),t('Bring complementary strengths in inference, KV Cache, and agents. Leave with a reproducible system and a verifiable body of work.','以推理、KV Cache、Agent 的互补能力组队，用可复现系统和可核验成果证明全栈工程实力。'),link('/involve/',t('Explore team participation','了解团队参与'),'button'))+subLayout([['teams',t('Who it is for','团队画像')],['journey',t('Your journey','参与路径')],['deliver',t('What to deliver','交付要求')],['after',t('What comes next','赛后机会')]],
    article('teams',t('Small teams. Full-stack thinking.','精干团队，全栈协同。'),`<p>${t('The first edition targets experienced engineers, doctoral researchers, and open-source contributors through direct invitation. The proposed selection is five teams from around eight candidates, with up to three members and one captain per team.','首届定邀面向有实绩的工程师、博士生与开源贡献者。计划从约 8 支候选团队中筛选 5 队，每队最多 3 人并指定队长。')}</p>`+rows([[t('Inference & systems','推理与系统'),t('Local serving, concurrency, prefill/decode, performance analysis, and stable operation.','本地推理服务、并发、Prefill / Decode、性能分析与稳定运行。')],['KV Cache',t('Correct reuse, tenant isolation, persistence, recovery, and honest end-to-end comparisons.','正确复用、租户隔离、持久化、恢复与真实的端到端对照。')],[t('Agent & application engineering','Agent 与应用工程'),t('Harness design, controlled tools, editable artifacts, testing, traces, and independent acceptance.','Harness 设计、受控工具、可编辑工件、测试、trace 与独立验收。')]])+notice(t('Capability coverage matters. Whether individual roles must be strictly separated, and the minimum team size, will be confirmed in the frozen rules.','重点是能力覆盖。是否严格按个人分角色、最低人数等事项，以赛前冻结规则为准。')))+
    article('journey',t('A body of work, built in public.','把能力，变成可复核履历。'),rows([[t('Connect','赛前建立连接'),t('Invitation, contribution review, team formation, environment checks, and rule briefing. Formal phase-two questions remain sealed.','定向邀请、履历核验、组队、环境预检与规则说明，第二阶段正式题保持隔离。')],[t('Deliver','赛中证明能力'),t('Build during the open-book phase. Run all three applications offline. Submit original outputs, source, traces, and complete usage records.','开卷搭建底座，断网完成三类应用，提交原始工件、源码、轨迹与完整用量记录。')],[t('Contribute','赛后持续贡献'),t('Audit, reproduce, maintain, publish technical findings, and help improve reference systems.','参与审计、复现、维护与技术分享，持续改进参考方案。')]]))+
    article('deliver',t('Working systems. Complete evidence.','可运行系统，完整证据链。'),rows([[t('Rebuildable runtime','可重建运行包'),t('Source, inference configuration, Harness, locked dependencies, versions and hashes, topology, install and recovery instructions.','源码、推理配置、Harness、依赖锁、版本哈希、拓扑及安装恢复说明。')],[t('Native application artifacts','原生应用工件'),t('PPTX; XLSX and analysis summary; research report, source index, evidence matrix, and tool traces.','PPTX；XLSX 与分析摘要；研究报告、来源索引、证据矩阵及工具轨迹。')],[t('Evidence & release package','证据与发布包'),t('All attempts, costs, tokens, timing, licenses, known limits, and a named maintainer. Sensitive credentials and unauthorized data are excluded from publication.','全部尝试、成本、token、耗时、许可证、已知局限与维护人。公开发布须去除凭据与未授权数据。')]]))+
    article('after',t('Your next contribution starts here.','下一次贡献，从这里延续。'),`<p>${t('Proven work may lead to maintainer roles, joint research, course development, or enterprise adaptation projects. Selection depends on contribution, capability, availability, and actual project needs.','可核验成果可成为维护者、联合研究、课程开发或企业适配项目的候选依据，具体依实际贡献、能力、时间与项目需求匹配。')}</p>${notice(t('An award is not a customer order or a guaranteed project. Strong contributors who do not win may also join future work.','获奖不等于获得订单或保证项目。未获奖的优秀贡献者也可参与后续共建。'))}${link('/resources/',t('Read the planning handbook','阅读筹备手册'))}`))+cta();}
  function enterprise(){return pageHero(t('FOR ENTERPRISES & INDUSTRY','面向企业与行业用户'),t('Start with a task.<br><em>Build lasting capability.</em>','从一项任务开始。<br><em>形成自己的采用能力。</em>'),t('Explore open-source agents through a bounded scenario, independent acceptance, and a team that can operate what it adopts.','以有边界的场景和独立验收探索开源智能体，让企业团队真正能够接手和运营。'),link('/involve/',t('Shape a pilot brief','准备场景试点简报'),'button'))+subLayout([['path',t('Adoption journey','采用路径')],['deployment',t('Deployment options','部署形态')],['training',t('Team capability','团队能力')],['success',t('Measuring value','价值衡量')]],
    article('path',t('One clear problem is a good beginning.','一个明确问题，就是好的起点。'),rows([[t('Define the need','需求共创'),t('Name a business owner. Describe the current workflow, baseline, data boundaries, and measurable acceptance conditions.','明确业务负责人、当前流程、现有基线、数据边界与可衡量的验收条件。')],[t('Try it safely','沙箱试用'),t('Use authorized synthetic or de-identified tasks. Examine output quality, complete cost, failure, and limitations.','使用获授权的合成或脱敏任务，核验结果质量、完整成本、失败与局限。')],[t('Learn to operate','团队实训'),t('Business, development, operations, and security roles practice defining, running, and accepting tasks independently.','业务、开发、运维与安全人员共同实训，独立定义、运行和验收任务。')],[t('Run a bounded pilot','场景试点'),t('Bind local systems, data, permissions, and approvals. Verify business results, recovery, and maintenance ownership.','重新绑定本地系统、数据、权限与审批，验证业务结果、恢复与维护责任。')],[t('Review, then expand','复盘与推广'),t('Expand only after acceptance. Authorized, generalized learnings can feed back into shared templates.','通过验收后再扩展。经授权的抽象经验回到公共模板。')]]))+
    article('deployment',t('A common foundation. Different realities.','共同底座，适配不同现实。'),table([t('Path','路径'),t('Fit','适用价值'),t('Before production','生产前验证')],[[t('Private deployment','私有化部署'),t('Approved enterprise network or VPC','企业批准的内网或 VPC'),t('Identity, audit, backup, capacity, maintenance','身份、审计、备份、容量与维护')],[t('Hybrid deployment','混合部署'),t('Local sensitive workloads; approved external capacity','敏感任务本地，通用任务按批准路由'),t('Data classification, egress approval, routing, fallback','数据分类、出域审批、路由与回退')],[t('SME SaaS','中小企业 SaaS'),t('Hosted applications and workflows','托管应用与工作流'),t('Tenant isolation, export/deletion, service quality','租户隔离、导出删除与服务质量')],[t('OPC & small teams','OPC 与小团队'),t('Research, build, deliver, and operate','覆盖研究、构建、交付与运营'),t('Budget, permissions, human approval, client data','预算、权限、人工批准与客户数据')]])+notice(t('These are adoption paths to validate over time. Competition results do not establish production readiness across all sectors, hardware, or deployment types.','以上部署路径须分阶段适配验证。赛事结果不能自动证明所有行业、硬件与部署形态均已生产就绪。')))+
    article('training',t('Adoption includes the people.','采用系统，也要培养能力。'),`<p>${t('Planned training covers business leaders, operators, developers, operations and security teams, educators, and small-company founders. Completion is judged through independent work: a pilot decision, an accepted task, a rebuildable system, or a recovery exercise.','计划中的培训覆盖业务负责人、运营、开发、运维安全、高校教师与 OPC。以独立实操评价：一份试点决策、一项验收任务、一套可重建系统，或一次恢复演练。')}</p>`)+
    article('success',t('Measure what changed.','看清真正改变了什么。'),`<div class="big-statement">${t('Better results.<br>Less time to acceptance.<br><em>A team that can take over.</em>','结果是否更好。<br>从提交到验收是否更快。<br><em>团队能否独立接手。</em>')}</div><p>${t('Compare quality, rework, human minutes, all-attempt cost, recovery, and actual business outcomes. Record new review and operating work alongside any work saved.','同时比较质量、返工、人工分钟、全部尝试成本、恢复与业务结果；既记录节省的工作，也记录新增审核和运维。')}</p>`))+cta();}
  function research(){return pageHero(t('FOR UNIVERSITIES & RESEARCHERS','面向高校与研究机构'),t('Real constraints.<br><em>Research that connects.</em>','真实约束。<br><em>有场景的研究。</em>'),t('Bring rigorous questions to a repeatable engineering environment. Connect experiments, open implementations, specifications, and teaching.','把严谨问题带入可重复的工程环境，连接实验、开放实现、规范与教学。'),link('/involve/',t('Propose a collaboration','提出共建方向'),'button'))+subLayout([['questions',t('Research questions','研究议题')],['participate',t('Collaboration paths','合作入口')],['unit',t('A practical starting unit','最小共建单元')]],
    article('questions',t('Good questions need a place to be tested.','好问题，需要真实检验的地方。'),`<div class="research-grid">${[[t('Cross-layer state & scheduling','跨层状态与调度'),t('Can cache, placement, and scheduling improve end-to-end task latency and complete cost?','缓存、放置与调度能否改善端到端任务时延和完整成本？')],[t('Reliability & human collaboration','可靠性与人机协同'),t('When should a system retry, stop, or escalate to a person?','何时重试、停止或升级人工，更有利于真实交付？')],[t('Semantics & grounded context','语义与上下文接地'),t('Can explicit semantics, provenance, and action contracts reduce errors?','显式语义、来源与动作契约能否减少错误？')],[t('Evaluation validity','评测有效性'),t('Does independent acceptance predict usefulness in enterprise scenarios?','独立验收能否预测企业场景的实际可用性？')],[t('Resource measurement','资源计量与治理'),t('How can reservations, retries, releases, and receipts be reconciled accurately?','如何准确核对预留、重试、释放与回执？')],[t('Learning & teaching','人才与教学方法'),t('Does practical training improve independent deployment and maintenance?','真实实训能否提升独立部署与维护能力？')]].map((v,i)=>`<div class="research-card"><span class="micro">0${i+1} / ${t('RESEARCH DIRECTION','研究方向')}</span><h3>${v[0]}</h3><p>${v[1]}</p></div>`).join('')}</div>`)+
    article('participate',t('More than a place on the judging panel.','成为共建者，而不只是评委。'),rows([[t('Joint research','联合研究'),t('Define questions, control experiments, reproduce systems, and build open implementations and reports.','定义问题、设计对照、复现系统，形成开放实现与研究报告。')],[t('Specifications & methods','规范与方法'),t('Review terminology, maturity, test methods, interoperability, and evidence-backed specification candidates.','参与术语、成熟度、测试方法、互操作与证据支持的规范候选评审。')],[t('Courses & educator workshops','课程与教师研修'),t('Co-develop modular courses, stable labs, capstone projects, and assessment methods.','共建模块化课程、稳定实验、结业项目与评价方法。')],[t('Students & mentors','学生与导师实践'),t('Contribute components, tests, reproduction, maintenance, or an invited competition team.','参与组件、测试、复现、维护或定邀参赛，形成真实作品与导师反馈。')]]))+
    article('unit',t('One question. Three kinds of expertise.','一个问题，三类专业能力。'),`<div class="big-statement">${t('An academic lead.<br>A scenario owner.<br><em>An engineering maintainer.</em>','一名学术负责人。<br>一名场景负责人。<br><em>一名工程维护者。</em>')}</div><p>${t('Start with a semester- or quarter-scale research package. Agree on the question, data permission, baseline, budget, milestones, authorship, and public output boundaries. The first planning target is one to two research packages and a course pilot.','以一个学期或季度的小规模研究任务包起步，约定问题、数据授权、基线、预算、里程碑、署名与公开范围。首轮目标为 1—2 个联合研究任务包与课程试讲。')}</p>${notice(t('Contributions determine credit. Negative results remain valuable. Authorship, publication, courses, and academic credit follow partner review and agreement.','以实际贡献确定署名，保留负结果。发表、课程与学分安排遵循合作方评审与约定。'))}`))+cta();}
  function resources(){return pageHero(t('RESOURCES / PLANNING HANDBOOK','资料中心 / 筹备手册'),t('The details.<br><em>Clearly, in one place.</em>','重要细节。<br><em>清楚，集中，可查阅。</em>'),t('A concise reference for the proposed format, evaluation, timeline, governance, and readiness decisions. Based on V1.3, dated 27 October 2026.','集中查阅赛制、评测、时间线、治理与就绪事项。依据 2026 年 10 月 27 日 V1.3 提案整理。'),`<button class="button ghost" data-action="print">${t('Print / save as PDF','打印 / 保存 PDF')}${arrow}</button>`)+subLayout([['downloads',t('Source deck','提案原稿')],['phase-one',t('Phase one','第一阶段')],['phase-two',t('Phase two','第二阶段')],['measurement',t('Measurement','计量口径')],['schedule',t('Schedule','执行时间线')],['governance',t('Governance & readiness','治理与就绪')]],
    article('downloads',t('The proposal, ready to explore.','从完整提案，了解全貌。'),`<a class="resource-row" href="/assets/OAIC_Challenge_Pitch_Executive_V1.3.pptx" download><span class="file-type mono">PPTX</span><div><h3>${t('Executive pitch · V1.3','生态合作路演提案 · V1.3')}</h3><p>${t('Original Chinese-language deck · 51 slides · October 2026','中文原稿 · 51 页 · 2026 年 10 月')}</p></div><span class="arrow">↓</span></a>${notice(t('This website summarizes the planning proposal. Dates, prizes, funding, detailed scoring, task budgets, role requirements, and final appointments require confirmation. The formally frozen rules take precedence.','本网站为规划提案的整理摘要。日期、奖金、资金、评分细则、题目预算、角色要求与任命仍须确认，正式冻结规则优先。'))}`)+
    article('phase-one',t('Phase one: six infrastructure tasks.','第一阶段：六项基础考题。'),`<p>${t('Hours 0–30. Open book. Original tasks, metrics, and the 25-point total are retained. Inputs include basic Linux, frozen models and dependencies, public practice tasks, interfaces, and quotas.','0—30 小时，开卷。保留原考题、指标与 25 分总分。输入包括基础 Linux、冻结模型依赖、公开练习任务、接口与资源配额。')}</p>`+table([t('Task','考题'),t('Points','分值'),t('Acceptance focus','验收重点')],[['I1 · '+t('Rebuild & deploy','重建与部署'),'4',t('Locked dependencies, hashes, tool/test loop, independent clean rebuild','依赖锁与哈希、工具测试闭环、干净环境独立重建')],['I2 · '+t('Inference & admission','推理服务与准入'),'4',t('Streaming, concurrency, quota, cancellation, overload, fairness','流式、并发、配额、取消、过载拒绝与公平准入')],['I3 · '+t('KV state management','KV 状态管理'),'6',t('Correct reuse/invalidation, tenant isolation, persistence, ablation','正确复用与失效、隔离、持久恢复与开关对照')],['I4 · '+t('Prefill/decode separation','PD 分离与选择'),'4',t('Real KV handoff, equal-resource comparison, adaptive fallback','真实 KV 交接、同资源对照与适应回退')],['I5 · '+t('Reliability & recovery','可靠性与恢复'),'4',t('Worker failure, tool timeout, restart, idempotency, resource release','worker 中断、工具超时、重启、幂等与资源释放')],['I6 · '+t('End-to-end evidence','全链路证据'),'3',t('Task-to-artifact trace, usage measurement, complete-cost reconciliation','任务到工件 trace、用量计量与完整成本对账')]])+faq([[t('Baseline load and qualification gates','基础负载与资格门槛'),t('Six workload classes: short interaction, long input, shared prefix, pause/resume, mixed workflow, and negative/fault tests. Each class has 25 requests at concurrency 1, 4, 8, and 16: 600 requests per round, two formal rounds. Qualification retains concurrent-8 success ≥98%, 60-minute load success ≥99%, and isolation, KV correctness, cancellation, budget, and audit controls.','六类负载：短输入、长输入、共享前缀、暂停恢复、混合工作流、负向故障。每类按并发 1、4、8、16 各 25 请求，每轮共 600 请求，正式两轮。资格保留并发 8 成功率 ≥98%、60 分钟负载成功率 ≥99%，以及隔离、KV 正确性、取消、预算和审计门禁。')],[t('Optional innovation and API comparisons','可选创新与 API 对照'),t('KV persistence, intelligent placement, joint scheduling, FPGA-assisted retrieval, compression, and custom KV fusion are observation fields, not mandatory implementations or extra points. No FPGA is assumed in the listed hardware. Online API comparisons belong only to permitted phase-one or later research and do not add to the 100-point score.','KV 存储恢复、智能放置、联合调度、FPGA 辅助检索、压缩交付与自研融合仅作观察，不是指定作业或额外加分。所列硬件不假定含 FPGA。联网 API 对照仅属获准的第一阶段或后续研究，不在 100 分外加分。')]]))+
    article('phase-two',t('Phase two: quality, then efficiency.','第二阶段：质量优先，兼顾效率。'),`<p>${t('Hours 30–168. All three categories are required. Each proposed 25-point category splits into 15 quality, 6 efficiency, and 4 reproducibility/evidence points.','30—168 小时，三类应用全部必做。建议每类 25 分，分为质量 15、效率 6、复现与证据 4。')}</p>`+table([t('Category','应用'),t('Quality / 15','质量 / 15'),t('Efficiency / 6','效率 / 6'),t('Evidence / 4','证据 / 4')],[[t('Editable PPT','可编辑 PPT'),t('Facts 5; editability 6; visual quality 4','事实 5；可编辑性 6；视觉 4'),t('Time 2; cost 2; tokens 2','时间 2；成本 2；token 2'),t('Rerun 2; trace 2','复跑 2；溯源 2')],[t('Financial analysis','财报分析'),t('Data/formulas 7; charts 5; conclusions 3','数据计算 7；图表 5；结论 3'),t('Time 2; cost 2; tokens 2','时间 2；成本 2；token 2'),t('Rerun 2; lineage 2','复跑 2；血缘 2')],['Deep Research',t('Sources 7; synthesis 5; structure/limits 3','来源 7；综合 5；结构局限 3'),t('Time 2; cost 2; tokens 2','时间 2；成本 2；token 2'),t('Rerun 2; trace 2','复跑 2；溯源 2')]])+faq([[t('Proposed task counts and single-run budgets','建议题量与单次预算'),t('Each category: six independent tasks × three clean-snapshot runs = 18 attempts; 54 across all categories. Initial single-run proposals: PPT 45 minutes/256K logical tokens, finance 45 minutes/256K, research 60 minutes/512K. Calibrate and freeze before competition. All attempts count; do not select only the best output.','每类 6 道独立题 × 3 次干净快照运行 = 18 次，三类共 54 次。初始单次建议：PPT 45 分钟 / 256K 逻辑 token；财报 45 分钟 / 256K；研究 60 分钟 / 512K。赛前校准冻结，全部尝试计入，不能只挑最佳结果。')],[t('Proposed efficiency gates and formula','建议效率门槛与公式'),t('Per category: mean quality ≥12/15, at least 15/18 complete acceptances, and all critical correctness/security gates passed. Otherwise efficiency is zero. Compare penalized time, complete cost, and logical tokens to the local reference system: f(r)=max(0,min(1,(1.25−r)/0.5)). Efficiency=2f(time ratio)+2f(cost ratio)+2f(token ratio). Champion eligibility requires all three categories to pass. These are proposed thresholds.','每类平均质量 ≥12/15、至少 15/18 次完整验收，且关键正确性与安全门禁全部通过，否则效率分为零。对照本地参考系统：f(r)=max(0,min(1,(1.25−r)/0.5))，效率分=2f(时间比)+2f(成本比)+2f(token 比)。冠军资格须三类均通过，以上门槛为建议。')],[t('Offline and human-intervention boundaries','闭卷与人工边界'),t('At hour 30 freeze the system and allowed assets before releasing sealed tasks. Only local DeepSeek, open-source Harness, frozen dependencies, fonts, OCR, chart/render tools, and provided images are allowed. No internet downloads, remote commercial agents, external model APIs, remote human solving, cross-team answer exchange, or manual output repair. Rule clarification and downtime requests must use a uniform recorded process.','第 30 小时先冻结系统与允许资产，再发隐藏题。仅限本地 DeepSeek、开源 Harness、冻结依赖、字体、OCR、图表渲染工具与统一图片。禁止联网下载、远程商业 Agent、外部模型 API、远程人工解题、跨队答案交换与手工补改工件。规则澄清和停机申请须统一留痕。')]]))+
    article('measurement',t('Measure the whole attempt.','计量，覆盖每一次尝试。'),rows([[t('Six headline metrics','六个主指标'),t('Task success rate, task completion P95, TTFT P95, single-stream token speed, SLA concurrency, and complete cost per successful task.','任务成功率、任务完成 P95、TTFT P95、单流 token/s、SLA 并发度、每成功任务完整成本。')],[t('Full denominators','完整分母'),t('Include failures, timeouts, retries, warm-up, checkpoints, and occupied resources. Zero successes means infinite cost per success.','包含失败、超时、重试、预热、检查点与占用资源。零成功时，每成功任务成本记为无穷大。')],[t('Tokens and cost','token 与成本'),t('Logical input tokens still count when served from cache. Report cache hits and physical compute separately. Include GPU, CPU, tools, storage, network, and all attempts in cost.','缓存命中的逻辑输入仍计 token，另报命中与物理计算。完整成本包含 GPU、CPU、工具、存储、网络与全部尝试。')],[t('Evidence identifiers','证据关联'),t('Connect team_id, task_id, run_id, attempt_id, trace_id, model calls, tool calls, artifact hashes, and acceptance decisions.','贯通 team_id、task_id、run_id、attempt_id、trace_id、模型、工具、工件哈希与验收结果。')]]))+
    article('schedule',t('A clear sequence. No invented countdown.','明确执行顺序，以就绪确认日期。'),table([t('Relative time','相对时间'),t('Work','工作重点')],[['0–12 h',t('Install, connect inference and tools; establish first end-to-end trace','安装，联通推理与工具，形成首条全链路轨迹')],['12–24 h',t('KV, scheduling, PD, failure, and isolation prechecks','KV、调度、PD、故障与隔离预检')],['24–30 h',t('Phase-one acceptance; freeze system snapshot','第一阶段验收，冻结系统快照')],['30–108 h',t('Release sealed application tasks; execute clean repeated runs','发放三类隐藏题，执行独立重复运行')],['108–144 h',t('Independent edit, recalculation, citation and quality checks','独立编辑、复算、引文核验与质量评审')],['144–160 h',t('Rebuild, reproduce, reconcile cost, scan security','重建复现、日志成本对账与安全扫描')],['160–168 h',t('Defense, score breakdown, appeals, sealed handover','答辩、分项成绩、申诉与封存交付')]])+notice(t('Team windows run sequentially. Maintenance/reset windows are additional. The planning target is an early-December start and completion by late January or before Spring Festival; final dates depend on readiness.','各队顺序运行，维护重置另用窗口。筹备目标为 12 月初启动，次年 1 月底或春节前完成，最终日期以就绪确认为准。')))+
    article('governance',t('Ready means accountable.','就绪，也意味着责任明确。'),rows([[t('Independent evaluation','独立与公平'),t('Equal-resource baselines, equivalent-difficulty sealed packs, anonymous artifacts, declared conflicts, trace retention, and written appeal rules. No automatic order-based bonus is assumed.','同资源基线、等难度隔离题包、匿名工件、利益披露、轨迹留存与书面申诉规则。不默认设置顺序补偿加分。')],[t('Ownership & acceptance','组织与接受'),t('SSC coordinates priorities; TOC reviews technical quality; BIC reviews business value; the secretariat and workgroups coordinate execution, maintenance, and publication. Appointments are not assumed complete.','SSC 协调方向，TOC 审查技术质量，BIC 核验业务价值，秘书处与工作组协调执行、维护和发布；不假定任命已完成。')],[t('Before launch','启动前确认'),t('Verify EdgePod topology, hosting, model loading, local toolchain, tasks and acceptance tools, network isolation, reset procedures, withdrawal/appeals, licenses, and post-event maintenance resources.','确认 EdgePod 拓扑与托管、模型装载、本地工具链、题目与验收器、断网清场、退赛申诉、许可与赛后维护资源。')],[t('Versioned outputs','版本化成果'),t('Label draft, candidate, validated, or archived versions. Keep competition snapshots immutable; record later fixes separately.','标注草案、候选、已验证或归档状态。比赛快照不可覆盖，赛后修复另建版本。')]])+`<p>${t('Source basis: supplied OAIC executive deck V1.3 and the accompanying planning text. This site does not independently verify referenced source documents that were not supplied.','依据：用户提供的 OAIC 路演提案 V1.3 与配套规划文本。未直接提供的上游参考文件，本站未作独立核验。')}</p>`));}
  function involve(){return pageHero(t('GET INVOLVED / START A CONVERSATION','参与共建 / 从一个具体提议开始'),t('Bring one thing.<br><em>Build something shared.</em>','带来一项贡献。<br><em>一起形成共同成果。</em>'),t('An expertise. A real problem. A resource. Start with a clear contribution and a milestone everyone can understand.','一项专业能力、一个真实问题、一份资源，从明确贡献与里程碑开始。'))+`<div class="wrap involve-grid"><div><h2>${t('Where would you like to contribute?','你希望从哪里参与？')}</h2><p>${t('Prepare a short brief to take into a collaboration conversation. Official invitations and contact channels will be announced by OAIC.','准备一份简短共建提议，带入后续合作讨论。正式定邀与联络入口由 OAIC 发布。')}</p>${[[t('Sponsor or resource partner','赞助或资源伙伴'),'partner'],[t('Team or open-source contributor','参赛或开源贡献者'),'team'],[t('Enterprise scenario owner','企业场景负责人'),'enterprise'],[t('Researcher or educator','研究者或教育工作者'),'research']].map(v=>`<button class="role-choice" data-action="role" data-role="${v[1]}">${v[0]}${right}</button>`).join('')}<p>${t('For official project information:','官方项目信息：')} <a class="text-link" href="https://www.oaic.ai/" target="_blank" rel="noopener">oaic.ai ${arrow}</a></p></div><div><h2>${t('A useful first brief.','让第一份提议更具体。')}</h2><p style="font-size:12px;color:var(--muted);margin:14px 0 25px">${t('Created in your browser. Download or copy it for your own use; this page does not send a registration.','在浏览器中生成，可自行下载或复制；本页不会提交报名。')}</p><form id="brief-form"><div class="field"><label for="role">${t('I would like to participate as','我希望以此身份参与')}</label><select id="role" name="role"><option value="partner">${t('Sponsor / resource partner','赞助 / 资源伙伴')}</option><option value="team">${t('Team / open-source contributor','参赛 / 开源贡献者')}</option><option value="enterprise">${t('Enterprise scenario owner','企业场景负责人')}</option><option value="research">${t('Researcher / educator','研究者 / 教育工作者')}</option></select></div><div class="field"><label for="contribution">${t('The contribution or problem','贡献内容或真实问题')} *</label><textarea id="contribution" name="contribution" required maxlength="3000" placeholder="${t('What can you contribute, or what would you like to validate?','你能提供什么？或希望验证什么？')}"></textarea></div><div class="field"><label for="milestone">${t('A first deliverable & milestone','首项交付与里程碑')} *</label><input id="milestone" name="milestone" required maxlength="500" placeholder="${t('A concrete outcome and a realistic time window','一项具体成果与合理的时间窗口')}"></div><button class="button" type="submit">${t('Create my brief','生成我的共建提议')}${arrow}</button></form><div id="brief-output" aria-live="polite"></div></div></div>`;}
  const prompts=[
    'A seamless 10-second architectural motion loop for an open-source AI engineering initiative. On a pale cool-white background, two sculptural electric-cobalt blue tubular triangular forms slowly approach, rotate, and interlock while retaining a small visible opening. Their silhouette subtly recalls two angular A peaks and broken circular strokes. Physically based glossy ceramic material, precise beveled edges, soft studio daylight, restrained shadows, premium design exhibition aesthetic. Slow deliberate movement, fixed camera, no cuts, no flashy particles. Sculpture placed in the right 55 percent, generous clean negative space on the left for web typography. Palette strictly cobalt #244BFF, cool white #F6F7F5, pale blue #E9EDFF, ink #171919. No orange, no warm lighting, no text, no lettering, no logos, no humans, no robots, no interface. First and last frames match. 16:9, 24 fps, 4K master.',
    'A seamless 8-second macro engineering film for an open-source full-stack agent challenge. Near-black graphite space. Three precise streams of acid-lime light travel across a minimalist layered architectural structure, meet at an open triangular frame, then resolve into three small clean geometric artifacts: a presentation sheet, a chart plane, and a research-page stack, represented only by abstract geometry without readable content. Camera drifts extremely slowly along a single smooth path. Industrial precision, dark anodized metal, luminous lime edges, sparse ice-cyan reflections, crisp spatial depth. Keep the left 50 percent quiet and almost black for typography. Palette #11150F, #D8FF3E, #8AE6FF. No orange, no purple gradients, no sparks, no circuit-board clichés, no humanoid robots, no text, no lettering, no logos. Understated continuous movement, no cuts. Return to the exact starting composition. 16:9, 24 fps, 4K master.',
    'A seamless 12-second editorial sculpture loop about collective intelligence. In a porcelain-white gallery, translucent sky-blue architectural ribbons and thin paper-like planes drift gently into a single open double-peak structure, leaving room between pieces so every contribution remains visible. The sculpture opens and relaxes back to the initial arrangement. Elegant tactile materials: frosted sky-blue glass, satin ice-blue ceramic, porcelain-white paper. Large soft shadows, diffuse neutral daylight, sculptural art direction, luxury cultural-publication aesthetic. Fixed camera, medium-wide framing, restrained shallow depth of field. Keep the subject in the right 55 percent and leave the left half empty for live website copy. Palette sky blue #8AE6FF, porcelain #F6FAFA, deep ink #102C3A, pale ice #E4F5FA. Broad, low architectural proportions echo an extended geometric wordmark. No purple, no orange, no gold, no pink lighting, no text or generated typography, no logos, no humans. No fast cuts or explosions. First frame and final frame identical. 16:9, 24 fps, 4K master.'
  ];
  const concepts=()=>[
    {id:'cobalt',name:'Electric Cobalt',tag:t('Original exploration','原始探索'),desc:t('Confident, architectural, and exceptionally clear. Cool white, oversized sans-serif type, and sculptural cobalt make the initiative feel serious without feeling institutional.','自信、建筑感、清晰。冷白留白、大字号无衬线字体与钴蓝雕塑，让项目既专业，也有鲜明个性。'),colors:['#244BFF','#F6F7F5','#171919','#E9EDFF'],best:t('The original cobalt exploration, retained for comparison.','保留最初的钴蓝色探索，便于对比。'),ref:'https://www.pentagram.com',refName:'Pentagram',refWhy:t('graphic clarity & art direction','图形秩序与艺术指导'),film:t('Open assembly','开放的组合'),story:t('Separate open forms become one structure. A visual metaphor for existing open-source components working together without becoming a closed platform.','开放的独立形体形成共同结构，象征已有开源组件协同工作，同时保留开放与可替换空间。'),duration:'10 s'},
    {id:'acid',name:'Acid Signal',tag:t('Most expressive','最有冲击力'),desc:t('A precise, after-dark engineering language. Near-black surfaces and sharp lime make a bold statement, with monospaced details that feel at home with systems builders.','精密的深色工程语言。近黑底色与明亮青柠形成强烈对比，等宽细节呼应系统开发者的世界。'),colors:['#D8FF3E','#11150F','#F0F3E9','#8AE6FF'],best:t('Best for an elite engineering challenge with a strong event identity.','适合强调精英工程挑战与鲜明赛事身份。'),ref:'https://linear.app',refName:'Linear',refWhy:t('precision, hierarchy & motion restraint','精确层级与克制动效'),film:t('From signal to substance','从信号到交付'),story:t('Three streams converge through a system and emerge as a presentation, a chart, and a report. It tells the full-stack story through tangible outputs.','三条信号穿过系统，形成演示稿、图表与研究报告，用具体工件讲清全栈协同的意义。'),duration:'8 s'},
    {id:'iris',name:'Sky Editorial',tag:t('Selected direction','已选方向'),desc:t('The third direction, refined around sky blue #8AE6FF. Naturally wide geometric type echoes the GAAC mark; deep ink, porcelain white, tactile forms, and generous space retain the editorial elegance.','以第三版为基础，用天蓝色 #8AE6FF、深墨蓝与瓷白重新搭配。更宽扁的几何字体呼应 GAAC 标志，保留拱形构图、材质感形体和充足留白。'),colors:['#8AE6FF','#F6FAFA','#102C3A','#E4F5FA'],best:t('The chosen direction: an airy, elegant identity with a wider, lower typographic rhythm.','当前主方向：轻盈优雅，以更宽、更低的字体比例连接 GAAC 的品牌形态。'),ref:'https://www.cosmos.so',refName:'Cosmos',refWhy:t('editorial space & visual curation','编辑式留白与视觉策展'),film:t('Collective form','共同成形'),story:t('Sky-blue glass and pale ceramic find a shared open architecture. A calm expression of research, industry, open source, and education contributing to one ambition.','天蓝色玻璃与浅色陶瓷共同构成开放建筑，以平静、通透的方式表达研究、产业、开源与教育的共同投入。'),duration:'12 s'}
  ];
  function directions(){return `<div class="wrap design-page"><section class="design-intro">${eyebrow(t('GAAC / A VISUAL DIRECTION TO BUILD ON','GAAC / 从视觉方向开始'),true)}<h1>${t('Three perspectives.<br>One open ambition.','三种视觉表达。<br>同一个开放愿景。')}</h1><p>${t('Compare three complete directions using the same content and page structure. The supplied GAAC mark remains the anchor: open strokes, angular peaks, and forward movement. Every palette excludes orange.','三种设计使用相同的信息架构与内容，便于直接比较。保留 GAAC 标志，以开放线条、几何山峰与向前的动势为灵感。所有配色均不含橙色。')}</p></section><section class="direction-overview" id="compare"><div class="overview-heading"><span class="micro">${t("THREE LIVE DESIGN DIRECTIONS","三种可体验的设计方向")}</span><a href="#films" class="text-link">${t("Hero film ideas","首屏视频灵感")} ${arrow}</a></div><div class="direction-tiles">${concepts().map((c,i)=>`<a class="direction-tile" href="${href("/",c.id)}"><img src="/assets/design-${c.id}.png?v=sky-cn-r3b" alt="${c.name} ${t("homepage preview","首页预览")}"><div class="tile-heading"><span class="micro">0${i+1}</span><h2>${c.name}</h2>${arrow}</div><div class="tile-colors">${c.colors.map(v=>`<span><i style="background:${v}"></i>${v}</span>`).join("")}</div></a>`).join("")}</div></section>${concepts().map((c,i)=>`<section class="design-concept" id="${c.id}"><a class="design-preview" href="${href('/',c.id)}"><span class="preview-fallback" style="background:${c.colors[1]};color:${c.colors[0]}">${c.name}</span><img src="/assets/design-${c.id}.png?v=sky-cn-r3b" alt="${c.name} — ${t('actual homepage screenshot','实际首页截图')}" loading="lazy" onerror="this.remove()"><span class="image-caption">${t('Actual website preview · click to explore','实际网站预览 · 点击探索')} ↗</span></a><div><div class="concept-title"><div><span class="micro">DIRECTION 0${i+1}</span><h2>${c.name}</h2></div><span class="recommend">${c.tag}</span></div><p class="concept-desc">${c.desc}</p><div class="swatches" aria-label="${c.name} ${t('color palette','配色')}">${c.colors.map(color=>`<div class="swatch"><div class="swatch-color" style="background:${color}"></div><div class="swatch-label">${color}</div></div>`).join('')}</div><p class="concept-meta"><b>${t('Best for:','适合：')}</b> ${c.best}<br><b>${t('Reference:','参考：')}</b> <a href="${c.ref}" target="_blank" rel="noopener">${c.refName} ↗</a> · ${c.refWhy}</p>${link('/',t('Explore this direction','探索这一方向'),'button',c.id)}<a class="reference-link" href="${c.ref}" target="_blank" rel="noopener">${t('View reference','查看参考')} ↗</a></div></section>`).join('')}<section class="section" id="films">${sectionLabel('04',t('HERO FILM CONCEPTS','首屏视频概念'))}<div class="section-header"><h2>${t('Make the idea move.','让理念，动起来。')}</h2><p class="section-intro">${t('These are generation-ready film briefs. The homepages currently use original, live canvas motion studies; no AI videos have been generated or represented as finished.','以下是可用于 AI 视频生成的创意简报。首页现用原创实时 Canvas 动效作为视觉研究，尚未生成 AI 视频。')}</p></div>${concepts().map((c,i)=>`<article class="video-card"><div><span class="micro">0${i+1} / ${c.name} / ${c.duration} LOOP</span><h3>${c.film}</h3><p>${c.story}</p></div><div class="prompt-box"><p>${prompts[i]}</p><button data-action="copy-prompt" data-prompt="${i}">${t('Copy generation prompt','复制生成提示词')} ${arrow}</button></div></article>`).join('')}${notice(t('Production brief: generate a 16:9 4K master, then export a muted, seamless 1080p WebM with MP4 fallback. Keep website text outside the film. Aim for a light mobile asset (about 3–6 MB), provide a poster image and a visible pause control, and use the poster for reduced-motion or data-saving preferences. Crop the right-hand composition for mobile. Exact output size depends on duration and visual complexity.','制作建议：生成 16:9、4K 母版，压缩为静音循环 1080p WebM，附 MP4 回退。文字由网页渲染。移动端建议控制在约 3—6 MB，提供静态封面与暂停按钮，并尊重减少动态效果及节流偏好。移动端裁切右侧主体，文件体积依时长与复杂度调整。'))}</section><section class="section pathways">${sectionLabel('05',t('A CLEARER INFORMATION ARCHITECTURE','更清晰的信息架构'))}<h2>${t('The right detail.<br>On the right page.','让每种信息，<br>找到合适的位置。')}</h2><div class="sitemap">${[['/',t('Home','首页'),t('The proposition, three tasks, and paths to participate','项目主张、三类应用与参与入口')],['/challenge/',t('The challenge','挑战赛'),t('Format, applications, platform, and key questions','赛制、应用、平台与常见问题')],['/ecosystem/',t('The ecosystem','开放生态'),t('Testbed, reusable outputs, capabilities, and 90-day plan','Testbed、共同成果、能力与 90 天计划')],['/partners/',t('Sponsors & partners','赞助伙伴'),t('Contribution types, value, and milestone reporting','合作方式、价值与里程碑报告')],['/teams/',t('Teams & builders','参赛团队'),t('Team profile, journey, deliverables, and opportunities','团队画像、路径、交付与后续机会')],['/enterprise/',t('Enterprise adoption','企业采用'),t('Trial, training, deployment, pilot, and acceptance','试用、培训、部署、试点与验收')],['/research/',t('Research & education','高校研究'),t('Research questions, courses, and collaboration units','研究问题、课程与最小共建单元')],['/resources/',t('Planning handbook','筹备手册'),t('Source deck, detailed rules, scoring, and readiness','提案原稿、详细规则、评分与就绪事项')],['/involve/',t('Get involved','参与共建'),t('Audience paths and a local collaboration-brief builder','分角色入口与本地共建提议生成')]].map(v=>`<a href="${href(v[0])}"><div>${v[1]}<small>${v[2]}</small></div>${arrow}</a>`).join('')}</div></section></div>`;}
  function render(){
    const version=++renderVersion;
    if(disposeArt){disposeArt();disposeArt=null;}
    const page=location.pathname.replace(/^\/+|\/+$/g,'').replace(/\/?index\.html$/,'')||'home';
    const pages={home,challenge,ecosystem,partners,teams,enterprise,research,resources,involve,directions};
    document.documentElement.dataset.theme=theme;
    document.documentElement.dataset.type=typeface;
    document.documentElement.dataset.cn=cnFont;
    document.documentElement.lang=lang==='zh'?'zh-CN':'en';
    document.body.className=theme+' '+page;
    document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();
    const names={home:t('Built open. Proven real.','开放共建，实战验证。'),challenge:t('The challenge','挑战赛'),ecosystem:t('The ecosystem','开放生态'),partners:t('Sponsors & partners','赞助伙伴'),teams:t('Teams & builders','参赛团队'),enterprise:t('Enterprise adoption','企业采用'),research:t('Research & education','高校研究'),resources:t('Planning handbook','筹备手册'),involve:t('Get involved','参与共建'),directions:t('Three design directions & hero films','三种设计方向与首屏视频')};
    document.title=`GAAC by OAIC — ${names[page]||'Page not found'}`;
    app.innerHTML=header(page)+`<main id="main">${pages[page]?pages[page]():`<div class="wrap not-found"><p class="eyebrow">404</p><h1>${t('An open question.','尚未找到这一页。')}</h1><p>${t('This page does not exist. Let’s get you back to the challenge.','这一页不存在，返回首页继续探索。')}</p>${link('/',t('Back to home','回到首页'),'button')}</div>`}</main>`+footer()+dock();
    persist('gaac-design-v2',theme);persist('gaac-language',lang);persist('gaac-typeface',typeface);persist('gaac-cn-font',cnFont);
    if(page==='home')import('/art.js?v=sky-cn-r3b').then(({createSculpture})=>{if(version!==renderVersion)return;disposeArt=createSculpture(document.querySelector('#sculpture'),theme,document.querySelector('.motion-toggle'));}).catch(()=>{document.querySelector('.motion-toggle')?.remove();});
    if(page==='involve'){
      const role=new URLSearchParams(location.search).get('role');
      if(role&&['partner','team','enterprise','research'].includes(role))document.querySelector('#role').value=role;
      document.querySelector('#brief-form').addEventListener('submit',makeBrief);
    }
    if(location.hash){requestAnimationFrame(()=>{let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{return}document.getElementById(id)?.scrollIntoView({block:'start',behavior:'instant'});});}
  }
  function setState(){const url=new URL(location.href);url.searchParams.set('design',theme);url.searchParams.set('lang',lang);url.searchParams.set('type',typeface);url.searchParams.set('cn',cnFont);history.replaceState({},'',url);render();}
  function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3000);}
  async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('Copied to clipboard','已复制到剪贴板'));return true}catch{toast(t('Clipboard unavailable. Select and copy the text.','剪贴板暂不可用，请选择文字复制。'));return false}}
  function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  let brief='';
  function makeBrief(e){e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const roleField=form.elements.namedItem('role');const role=roleField.options[roleField.selectedIndex].text;brief=`GAAC / OAIC — ${t('COLLABORATION BRIEF','共建提议')}\n\n${t('Participation path','参与身份')}: ${role}\n\n${t('Contribution / problem','贡献 / 问题')}:\n${form.elements.namedItem('contribution').value.trim()}\n\n${t('First deliverable / milestone','首项交付 / 里程碑')}:\n${form.elements.namedItem('milestone').value.trim()}\n\n${t('To agree together: owner, scope, resources, acceptance, data permissions, maintenance, and official contact.','待共同确认：负责人、范围、资源、验收、数据授权、维护与正式联络方式。')}\n\n${t('Prepared locally. Not a registration or an accepted agreement. Official information: https://www.oaic.ai/','本地生成，不构成报名或合作承诺。官方信息：https://www.oaic.ai/')}`;const out=document.querySelector('#brief-output');out.className='form-result';out.innerHTML=`<strong>${t('Your brief is ready.','共建提议已生成。')}</strong><textarea readonly aria-label="${t('Your collaboration brief','你的共建提议')}"></textarea><button class="button small" data-action="download-brief">${t('Download brief','下载提议')} ↓</button> <button class="button small ghost" data-action="copy-brief">${t('Copy','复制')}</button>`;out.querySelector('textarea').value=brief;out.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}
  document.addEventListener('click',e=>{
    const target=e.target.closest('[data-action]');if(!target)return;
    const action=target.dataset.action;
    if(action==='theme'){theme=target.dataset.theme;setState();}
    if(action==='language'){lang=lang==='en'?'zh':'en';setState();}
    if(action==='menu'){const nav=document.querySelector('#main-nav');const open=nav.classList.toggle('is-open');target.setAttribute('aria-expanded',String(open));target.setAttribute('aria-label',open?t('Close navigation','关闭导航'):t('Open navigation','打开导航'));target.textContent=open?'×':'☰';}
    if(action==='print')window.print();
    if(action==='role'){document.querySelector('#role').value=target.dataset.role;document.querySelector('#contribution').focus();}
    if(action==='copy-prompt')copy(prompts[Number(target.dataset.prompt)]);
    if(action==='download-brief')download(brief,'GAAC-collaboration-brief.txt');
    if(action==='copy-brief')copy(brief);
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.nav-dropdown[open]').forEach(d=>d.open=false);document.querySelector('#main-nav')?.classList.remove('is-open');const b=document.querySelector('.mobile-toggle');if(b){b.setAttribute('aria-expanded','false');b.textContent='☰';}}});
  addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);theme=themes.includes(p.get('design'))?p.get('design'):theme;lang=['en','zh'].includes(p.get('lang'))?p.get('lang'):lang;typeface=typefaces.includes(p.get('type'))?p.get('type'):typeface;cnFont=cnFonts.includes(p.get('cn'))?p.get('cn'):cnFont;render();});
  render();
})();
